{
  "spans": [
    {
      "label": "QUOTE",
      "frame": "རྗེ་ཡང་དགོན་པས་ནི།",
      "head": "དོན་སྤྱི་མ་ནོར་བ་བློ་ཡུལ་དུ་ཤར་བ་གོ་བ། རང་མཚན་གྱི་རྣམ་པ་ཕྱོགས་གཅིག་ཉམས་འོག་ཏུ་ཚུད་པ་ཉམས་མྱོང་། རང་མཚན་མ་འཁྲུལ་བར་མངོན་དུ་གྱུར་པ་ལ་རྟོགས་པ་",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "ཡང་ན། བློ་ཡུལ་དུ་ཤར་ནས་ཡིད་ཆེས་པ་གོ་བ། དེ་སེམས་ཀྱི་མྱོང་བ་ཉམས། སེམས་རང་དེའི་ངོ་བོར་ཤར་བ་ལ་རྟོགས་པ་",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "གོང་མ་ཕལ་ཆེ་བས།",
      "head": "རྩེ་གཅིག་རྣམ་རྟོག་བཟུང་དྲན། སྤྲོས་བྲལ་སྟོང་ཉིད་དྲན་པ། རོ་གཅིག་སྐྱེ་མེད་དྲན་པ། སྒོམ་མེད་བློ་འདས་དྲན་པ།",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "རྩེ་གཅིག་གོང་དང་འདྲ་བ་ལ། སྤྲོས་བྲལ་སྐྱེ་མེད་དྲན་པ། རོ་གཅིག་བློ་འདས་དྲན་པ། སྒོམ་མེད་དབྱིངས་སུ་ཐིམ་པ།",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "རྗེ་སྒོམ་ཆུང་གིས།",
      "head": "ངང་ལ་གནས་པ་རྩེ་གཅིག་ཡིན། །སྒྲོ་འདོགས་ཆོད་པ་སྤྲོས་བྲལ་ཡིན། །སྤང་བླང་མེད་ན་རོ་གཅིག་ཡིན༑ །མྱོང་བ་དག་ན་སྒོམ་མེད་ཡིན། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "རྗེ་སྒོམ་ཆུང་གིས།",
      "head": "རྩེ་གཅིག་དུས་སུ་ངོ་བོ་རྟོགས། །སྤྲོས་བྲལ་དུས་སུ་རང་བཞིན་རྟོགས། །རོ་གཅིག་སྣང་བའི་མཚན་ཉིད་རྟོགས། །སྒོམ་མེད་རྟོགས་པ་ཁོར་ཡུག་མ། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "རྗེ་དེས།",
      "head": "རྩེ་གཅིག་མུན་པའི་དཀྱིལ་ན་འབྱམས༑ །སྤྲོས་བྲལ་མེད་པའི་སྟོང་རྩིས་ཁྱེར། །རོ་གཅིག་འདྲེས་པའི་རྦ་ལ་གཡེངས། །སྒོམ་མེད་ཉི་མ་སྤྲིན་གྱིས་སྒྲིབ༑ །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "རྗེ་དེས།",
      "head": "རྩེ་གཅིག་གི་རྗེས་ཤེས་ཨ་འཐས་སུ་སྐྱེ། །སྤྲོས་བྲལ་གྱི་རྗེས་ཤེས་སྒྱུ་མར་སྐྱེ། །རོ་གཅིག་གི་རྗེས་ཤེས་སྟོང་པར་སྐྱེ། །སྒོམ་མེད་ཀྱི་རྗེས་ཤེས་སྙིང་རྗེར་སྐྱེ། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "རྗེ་དེས།",
      "head": "རྩེ་གཅིག་ལ་དངོས་འཛིན་གྱི་དྲི་མ་ཡོ༑། །སྤྲོས་བྲལ་ལ་ངོ་མ་ཤེས་ཀྱི་དྲི་མ་ཡོད། །རོ་གཅིག་ལ་ཉམས་ཀྱི་དྲི་མ་ཡོད། །སྒོམ་མེད་ལ་ཤེས་བྱའི་དྲི་མ་ཡོད། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "རྗེ་དེས།",
      "head": "རྩེ་གཅིག་བྲལ་ཡོད་ཐོབ་པ་མེད། །སྤྲོས་བྲལ་བྲལ་ཐོབ་གཉིས་ཀ་ཡོད། །རོ་གཅིག་བྲལ་མེད་ཐོབ་པ་ཡོད། །སྒོམ་མེད་བྲལ་ཐོབ་གཉིས་ཀ་མེད། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "རྗེ་དེས།",
      "head": "རྩེ་གཅིག་རང་སའི་མཉམ་རྗེས་ཡོད། །སྤྲོས་བྲལ་མཉམ་རྗེས་སོ་སོར་འབྱེད། །རོ་གཅིག་དུས་སུ་མཉམ་རྗེས་འདྲེས། །སྒོམ་མེད་མཉམ་བཞག་འབའ་ཞིག་གོ །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "རྗེ་དེས།",
      "head": "རྩེ་གཅིག་ཨ་འཐས་སྒོམ་པའི་དུས། །སྤྲོས་བྲལ་སྟོང་པར་སྒོམ་པའི་དུས༑ །རོ་གཅིག་ཟུང་འཇུག་སྒོམ་པའི་དུས། །སྒོམ་མེད་མངོན་དུ་གྱུར་བའི་དུས། །",
      "tail": ""
