    {
      "label": "QUOTE",
      "frame": "ཆོས་རྗེ་རྒྱ་རས་ཀྱིས།",
      "head": "རྩེ་གཅིག་ཉམས་ཀྱི་མཐོ་དམན་ཡིན། །",
      "tail": "བྱ་རྩོལ་ཐམས་ཅད་དབྱིངས་སུ་ཐིམ། །"
    },
    {
      "label": "QUOTE",
      "frame": "དེ་བཞིན་གཙང་སྨྱོན་གྱིས།",
      "head": "སྣང་གྲགས་ཀྱི་ཆོས་ཐམས་ཅད་ཐོལ་སྐྱེས་ཀྱི་རིག་པ་སྐད་ཅིག་མའི་སྟེང་དུ་རྫོགས་ཤིང་ཚང་ལ།",
      "tail": "རོ་གཅིག་གི་དུས་ན་བློ་ལས་འདས་པས་ན་སྒོམ་མེད་དོ། །"
    },
